CREATE POLICY "owner_or_admin_select" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'product-imports' AND ((storage.foldername(name))[1] = auth.uid()::text OR public.is_admin(auth.uid())));
CREATE POLICY "owner_or_admin_insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'product-imports' AND ((storage.foldername(name))[1] = auth.uid()::text OR public.is_admin(auth.uid())));
CREATE POLICY "owner_or_admin_update" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'product-imports' AND ((storage.foldername(name))[1] = auth.uid()::text OR public.is_admin(auth.uid())));
CREATE POLICY "owner_or_admin_delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'product-imports' AND ((storage.foldername(name))[1] = auth.uid()::text OR public.is_admin(auth.uid())));